async function refreshWorld(){const previous=world;world=await request('/api/world');const banner=document.querySelector('.server-banner');if(banner){banner.hidden=!world.management?.maintenance&&!world.management?.announcement;banner.textContent=[world.management?.maintenance?'SERVER ĐANG BẢO TRÌ':'',world.management?.announcement?.text||''].filter(Boolean).join(' · ');}watchWorld(previous,world);if(chatVisible()&&chatMode==='guild')lastSeenGuild=world.guildMessages.at(-1)?.time||lastSeenGuild;if(chatVisible()&&chatMode==='global')lastSeenChat=world.messages.at(-1)?.time||lastSeenChat;}
