const button=(label,action,id='',disabled=false)=>`<button data-action="${action}" data-id="${id}" ${disabled?'disabled':''}>${uiLabel(label,settings(s).language)}</button>`;
const tabs=[['hub','⌖','Trung tâm'],['map','⌖','Bản đồ'],['rail','♧','Ga tàu'],['dungeon','▥','Dungeon'],['inventory','▣','Trang bị'],['missions','≡','Nhiệm vụ'],['chat','▱','Trò chuyện'],['reputation','♙','Uy tín'],['rewards','◇','Tiếp tế ngày'],['lore','!','Ký ức Neon'],['cores','⬡','Lõi AI'],['bazaar','▥','Khu chợ'],['market','▥','Chợ người chơi'],['alley','◇','Hẻm thông tin'],['pets','♧','Neon Paws'],['tavern','♧','Partyline'],['coast','≈','Bờ biển'],['shop','₡','Cửa hàng'],['black','◉','Chợ đen'],['station','⚒','Hiệu chuẩn'],['printer','▣','Máy in'],['bank','▥','Ngân hàng'],['exchange','◇','Đổi Unit'],['terminal','◈','Terminal'],['commercial','◷','Khu thương mại'],['afk','◷','Công việc AFK'],['corporation','♙','Tập đoàn'],['headquarters','♙','Trụ sở'],['housing','▦','Căn hộ'],['cosmetics','◈','Cyberwear'],['medical','✚','Trinoky'],['npc','◇','NPC'],['boss','♜','Boss'],['arena','⚔','Đấu trường'],['rank','↗','Xếp hạng'],['codex','▤','Kho dữ liệu'],['account','◎','Tài khoản'],['settings','⚙','Cài đặt'],['admin','⚒','Quản trị']];
function card(title,body,footer='',extra=''){return `<article class="card ${extra}"><h3>${esc(title)}</h3>${body}<div class="card-actions">${footer}</div></article>`;}
const slotName=slot=>slotLabels[slot]||slot;
function icon(slot){
 const shapes={special:'M5 24h46v14H29l-4 16H14l5-16H5zM43 19h13v6H43z',destructive:'M4 21h51l7 11-7 11H16L4 39zM18 43h9v10h-9zm25 0h9v10h-9z',helmet:'M8 34C8 3 53 3 56 34v17H36V35H23v21H8z',legs:'M17 7h30v21L40 58H29l3-28-8 28H12l5-30z',boots:'M15 7h17v26l22 9v14H8V39l7-6z',backpack:'M20 10h24v6h8v40H12V16h8zm5 0v6h14v-6zM20 36v14h24V36z'};
 if(shapes[slot])return `<svg viewBox="0 0 64 64" aria-hidden="true" fill="currentColor"><path d="${shapes[slot]}"/></svg>`;
 return `<svg viewBox="0 0 64 64" aria-hidden="true" fill="currentColor">${['weapon','special','destructive'].includes(slot)?'<path d="M6 22h38v-6h8v6h9v9H35l-4 16H19l4-16H6z"/><path d="M12 17h22v3H12z"/>':slot==='armor'?'<path d="m17 9 10-4 5 10 5-10 10 4 12 18-12 8-4-8v32H21V27l-4 8-12-8z"/>':'<path d="M17 17h30v30H17zM9 9h8v8H9zm38 0h8v8h-8zM9 47h8v8H9zm38 0h8v8h-8zM26 4h4v13h-4zm9 0h4v13h-4zM26 47h4v13h-4zm9 0h4v13h-4zM4 26h13v4H4zm0 9h13v4H4zm43-9h13v4H47zm0 9h13v4H47z"/>'}</svg>`;}
function gearCard(g,shop=false,compact=false){const price=shopPrice(g,online?world?.discount||0:0);const equipped=Object.values(s.equipped).includes(g.id),owned=s.inventory.includes(g.id)||s.housing?.storage?.includes(g.id)||s.escrow?.includes(g.id),v=itemStats(s,g.id),c=calibration(s,g.id);return `<article class="gear-card equipment-tile tier${g.rarity} ${shop?'shop-row':''}"><div class="gear-label"><span>${slotName(g.slot)}</span><span title="${rarities[g.rarity]}">${gearMark(g).name}</span></div><div class="gear-body"><button class="gear-open" data-action="detail" data-id="${g.id}" aria-label="Chi tiết ${esc(g.name)}"><span class="gear-icon">${icon(g.slot)}<small>LV ${g.level}</small></span><span class="gear-info"><strong>${esc(g.name)}${c.level?` +${c.level}`:''}</strong><span class="gear-numbers">${['weapon','special','destructive'].includes(g.slot)?'DMG':['armor','helmet','legs','boots'].includes(g.slot)?'DEF':'PWR'}: ${v.power}${v.damage?` · ATK: +${v.damage}`:''}${v.health?` · HP: +${v.health}`:''}${v.armor?` · DEF: +${v.armor}`:''}${v.crit?` · CRIT: +${Math.round(v.crit*100)}%`:''}${v.shield?` · SHIELD: ${v.shield}`:''}${v.pocket?` · POCKET: ${v.pocket}`:''}${v.regen?` · REGEN: ${v.regen}`:''}</span><span class="gear-sub">${rarities[g.rarity]} · CHẤT LƯỢNG ${v.quality}%${equipped?' · ĐANG MẶC':''}</span></span><span class="gear-sockets" aria-label="${slots(s,g.id)} khe module; đã lắp ${c.modules.filter(Boolean).length}">${Array.from({length:slots(s,g.id)},(_,i)=>`<i class="${c.modules[i]?'filled':''}"></i>`).join('')}</span><span class="gear-grade" title="Cấp trang bị">${g.level}</span></button></div><div class="gear-actions" ${compact?'hidden':''}>${shop?button(owned?'Đã sở hữu':`${price.toLocaleString('vi')} ₡`,'buy',g.id,owned||g.level>s.level||s.credits<price||!!s.combat):button(equipped?'Đang dùng':'Trang bị','equip',g.id,equipped||g.level>s.level||!!s.combat)+button(`Bán ${Math.floor(g.price*0.4)} ₡`,'sell',g.id,equipped||!!s.combat)}</div></article>`;}
function inventory(side=false){const html=inventoryView({s,section:side?workspaceInventoryTab:inventoryTab,subsection:side?workspaceBagSection:bagSection,filter:side?workspaceFilter:filter,search:side?workspaceSearch:search,sort:bagSort,selected:bagSelected,craftCategory,hideUnavailable,inboxPage,esc,button,gearCard:g=>gearCard(g,false,true),icon,slotName});return side?html.replace(/id="(search|bag-sort|hide-unavailable)"/g,(_,id)=>`id="workspace-${id}"`):html;}
function communications(){return commsView({s,world,online,mode:chatMode,replyId,attached,esc,button});}
function shop(){const black=tab==='black',selling=shopTab==='sell',list=gear.filter(g=>selling?s.inventory.includes(g.id):g.black===black).filter(g=>filter==='all'||g.slot===filter),visible=filtered(list),pages=Math.max(1,Math.ceil(visible.length/10));catalogPage=Math.min(catalogPage,pages-1);return `<div class="merchant ${black?'underground':''}"><img src="/src/merchant.svg" alt="Thợ vũ khí tóc bạc trong xưởng công nghệ neon"><div class="merchant-title"><span>${black?'FREQUENCY / 09.71':'HELIX / WORKSHOP 07'}</span><h1>${black?'Chợ bóng tối':'Thợ vũ khí'}</h1></div><div class="merchant-dialogue"><b>${black?'VEX / MÔI GIỚI':'KAIA / THỢ CHẾ TẠO'}</b><p>${black?'Không hỏi nguồn gốc. Chọn thứ giúp bạn sống sót.':'Đừng để món đồ rẻ tiền quyết định số phận. Cần gì, runner?'}</p></div></div><div class="subtabs">${[['buy','Mua trang bị'],['sell','Bán trang bị']].map(([id,name])=>`<button class="${shopTab===id?'selected':''}" data-action="shop-tab" data-id="${id}">${name}</button>`).join('')}<span>${s.credits.toLocaleString('vi')} ₡</span></div>${toolbar(true)}<div class="section-label">${selling?'KHO CỦA BẠN':black?'HÀNG CẤM / SỬ THI & HUYỀN THOẠI':'DANH MỤC THIẾT BỊ'}<span>${visible.length} MỤC</span></div><div class="shop-list">${visible.slice(catalogPage*10,catalogPage*10+10).map(g=>gearCard(g,!selling)).join('')||'<p class="hint">Không có trang bị phù hợp.</p>'}</div><div class="pagination">${button('‹ Trước','catalog-page',String(catalogPage-1),catalogPage===0)}<span>TRANG ${catalogPage+1} / ${pages}</span>${button('Sau ›','catalog-page',String(catalogPage+1),catalogPage>=pages-1)}</div>`;}
function detail(){const g=gear.find(g=>g.id===selectedGear);return equipmentDetailView({s,g,esc,button,icon,slotName,online,world});}
function filtered(items){return items.filter(x=>x.name.toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')));}
function toolbar(options=false){return `<div class="toolbar"><input id="search" aria-label="Tìm kiếm nội dung" placeholder="Tìm trong mục này…" value="${esc(search)}">${options?`<select id="filter" aria-label="Loại trang bị"><option value="all">Tất cả loại</option>${equipmentSlots.map((x,i)=>`<option value="${x}" ${filter===x?'selected':''}>${slotName(x)}</option>`).join('')}</select>`:''}</div>`;}
function combat(){return combatView({s,online,esc,button});}
function authView(){return platformView({online,esc,button,unsafeUpdate:busy||!!s.combat||!!s.work||!!pendingDelete||!!adminPending})+authenticationView({s,online,providers:authProviders,esc,button,pending:googleBusy});}
function lootVisible(){return !!s.pendingLoot&&!s.combat&&!selectedGear&&!publicProfile&&['hub','terminal','boss','arena','dungeon','map'].includes(tab);}
function page(){if(lootVisible())return lootView({s,esc,button,icon,discard:lootDiscardId===s.pendingLoot.id});if(tab==='admin')return renderAdmin({online,data:adminData,section:adminSection,query:adminQuery,pending:adminPending,esc,button});if(tab==='rewards')return rewardsView({s,esc,button});if(tab==='lore')return loreView({s,esc,button});if(tab==='settings')return settingsView({s,online,draft:settingsDraft||settings(s),esc,button,returnTab:settingsReturn,accountSecurity:accountSecurityView({online,providers:authProviders,esc,pending:googleBusy})})+platformView({online,esc,button,unsafeUpdate:busy||!!s.combat||!!s.work||!!pendingDelete||!!adminPending});if(['bazaar','alley','pets','tavern','coast'].includes(tab))return bazaarView({s,tab,world,online,esc,button});if(tab==='afk')return afkPlannerView({s,id:afkJob,count:afkCount,world,online,esc,button});if(tab==='commercial')return commercialView({s,esc,button})+afkBoostPanel({s,world,online,esc,button});if(tab==='rail')return railView({s,station:railStation,esc,button});if(publicProfile)return button('‹ Đóng tài sản công khai','public-profile-close')+publicAssetsView(publicProfile,esc);if(tab==='missions'&&selectedMilestone)return milestonesView({s,esc,button,selected:selectedMilestone});if(tab==='cores'&&!selectedGear)return coresView({s,button});if(tab==='chat'&&!selectedGear)return communications();if(tab==='reputation'&&!selectedGear)return reputationView({world,online,esc,button});if(['market','corporation','headquarters','housing','cosmetics','medical','commercial'].includes(tab)&&!selectedGear)return worldView({s,tab,world,online,esc,button,marketSection,marketQuery,marketSlot,marketSort,marketDraft});if(s.combat&&['terminal','arena','boss'].includes(tab)&&!selectedGear)return combat();if(tab==='dungeon'&&!selectedGear)return dungeonView({s,esc,button,combat,online,world});if(selectedGear)return detail();if(['hub','station','printer','bank','exchange'].includes(tab))return serviceView({s,tab,esc,button,gearCard,options:stationOptions,calibrationId,financeAmount,world,online});const m=maps.find(x=>x.id===s.map);switch(tab){case 'terminal':return `<div class="hero"><div class="eyebrow">KẾT NỐI ĐÃ MÃ HÓA / SECTOR ${String(maps.indexOf(m)+1).padStart(2,'0')}</div><h1>Thành phố đã quên.<br><span>Bạn thì chưa.</span></h1><p>${esc(m.description)}</p><div class="actions">${button(s.dungeon?'Tiếp tục dungeon':'Vào dungeon','nav','dungeon')}${button('Khám phá · 2 EN','fight','',!!s.dungeon||!!s.combat||s.energy<2)}${button('Tìm nhiệm vụ','nav','missions')}${button('Nghỉ tại trạm','rest','',!!s.dungeon||!!s.combat)}</div><div class="hero-grid"><span>ĐỊA ĐIỂM<b>${esc(m.name)}</b></span><span>PHE KIỂM SOÁT<b>${esc(m.faction)}</b></span><span>TRẠNG THÁI<b class="green">${s.combat?'ĐANG CHIẾN ĐẤU':'TÍN HIỆU ỔN ĐỊNH'}</b></span></div></div>${keysView(s,esc,button,{assemble:true})}${combat()}${areaAFKActions({s,esc,button})}${nearbyView({s,esc,button})}<div class="section-head"><h2>Nhật ký hệ thống</h2><span>LIVE FEED</span></div><div class="feed">${s.log.map((x,i)=>`<p><span>${String(i+1).padStart(2,'0')}</span> ${esc(x)}</p>`).join('')}</div>`;
case 'map':return toolbar()+`<p class="hint">Di chuyển tốn 1 EN. Có thể vào khu vực cao hơn tối đa 2 cấp.</p><div class="grid">${filtered(maps).map(x=>card(x.name,`<div class="meta">Cấp ${x.level} · ${esc(x.faction)}</div><p>${esc(x.description)}</p>`,button(x.id===s.map?'Đang ở đây':x.level>s.level+2?'Chưa mở':'Di chuyển','move',x.id,x.id===s.map||x.level>s.level+2||!areaAccess(s,x)||!!s.dungeon||!!s.combat||s.energy<1))).join('')}</div>`;
case 'missions':return `<div class="mission-heading"><div><div class="eyebrow">${s.active.length} / 5 ĐANG NHẬN</div><h1>Hợp đồng</h1></div>${button('Tiếp tế ngày','nav','rewards')}</div><div class="mission-tools"><details class="dungeon-details" data-ui-panel="mission-community"><summary>Mục tiêu cộng đồng</summary>${communityView({world,s,online,esc,button})}</details><details class="dungeon-details" data-ui-panel="mission-progression"><summary>Nhiệm vụ tiến trình</summary>${milestonesView({s,esc,button})}</details><details class="dungeon-details" data-ui-panel="mission-guide"><summary>Hướng dẫn</summary>${guidanceView(button)}</details></div>`+'<div class="section-label">CONTRACTS / NHIỆM VỤ CÁ NHÂN <span>'+quests.length+' HỢP ĐỒNG</span></div>'+toolbar()+`<p class="hint">Tối đa 5 nhiệm vụ đang nhận. Chỉ lượt hạ địch sau khi nhận mới được tính.</p><div class="grid">${filtered(quests).sort((a,b)=>Number(s.active.includes(b.id))-Number(s.active.includes(a.id))).map(q=>{const active=s.active.includes(q.id),done=s.completed.includes(q.id),progress=questProgress(s,q);return card(q.name,`<div class="meta">Cấp ${q.level} · ${q.target==='boss'?'Hạ boss':'Hạ địch'} ×${q.count}</div><p>${esc(q.story)}</p><p class="reward">+${q.xp} XP / +${q.credits} ₡ ${active?`· ${progress}/${q.count}`:''}</p>`,button(done?'Đã hoàn thành':active?'Nhận thưởng':'Nhận nhiệm vụ',active?'claim':'accept',q.id,done||q.level>s.level+2||active&&(progress<q.count||!!s.combat)||!active&&s.active.length>=5));}).join('')}</div>`;
case 'inventory':return inventory();
case 'shop':case 'black':return shop();
case 'npc':return toolbar()+`<p class="hint">${npcs.length} cư dân của thành phố. Đến khu vực của họ để trò chuyện.</p><div class="grid">${filtered(npcs).map(n=>card(n.name,`<div class="meta">${esc(maps.find(m=>m.id===n.map).name)} · ${esc(n.faction)}</div>`,button('Trò chuyện','talk',n.id,n.map!==s.map||!!s.combat))).join('')}</div>`;
case 'boss':return combat()+toolbar()+`<div class="grid">${filtered(bosses).map(b=>card(b.name,`<div class="meta">Cấp ${b.level} · ${b.hp} HP · ${b.attack} ATK</div><p>${esc(b.description)}</p><p class="reward">+${b.xp} XP / +${b.credits} ₡</p>`,button('Thách đấu · 2 EN','boss',b.id,b.map!==s.map||!!s.dungeon||!!s.combat||s.energy<2))).join('')}</div>`;
case 'arena':if(online)return `<div class="hero"><div class="eyebrow">PVP / BẤT ĐỒNG BỘ</div><h1>Đấu trường<br><span>runner.</span></h1><p>Đấu với bản sao phòng thủ của nhân vật người chơi thật. Đối thủ do máy điều khiển; không yêu cầu họ online cùng lúc. Kết quả và phần thưởng của bạn được xử lý trên server.</p><p>${s.wins} thắng / ${s.losses} thua</p>${button('Nghỉ tại trạm','rest','',!!s.dungeon||!!s.combat)}</div>${combat()}<div class="grid" style="margin-top:20px">${players.filter(p=>p.id!==online.id).map(p=>card(p.name,`<p>Cấp ${p.level} · ${p.score} điểm</p>`,button('Thách đấu · 3 EN','pvp',p.id,!!s.dungeon||!!s.combat||s.energy<3))).join('')||'<p class="hint">Chưa có người chơi khác. Cần thêm một tài khoản tham gia đấu trường.</p>'}</div>`;return `<div class="hero"><div class="eyebrow">ARENA / ĐỐI THỦ MÔ PHỎNG</div><h1>Không có chỗ<br><span>cho tín hiệu yếu.</span></h1><p>Đấu tay đôi theo lượt với runner máy có cấp tương đương. Bản này chưa kết nối người chơi khác.</p><div class="actions">${button('Tìm đối thủ · 3 EN','pvp','',!!s.dungeon||!!s.combat||s.energy<3)}${button('Nghỉ tại trạm','rest','',!!s.dungeon||!!s.combat)}</div><div class="hero-grid"><span>THẮNG<b>${s.wins}</b></span><span>THUA<b>${s.losses}</b></span><span>ĐIỂM ĐẤU<b>${Math.max(0,s.wins*25-s.losses*10)}</b></span></div></div>${combat()}`;
case 'rank':{if(online)return `<p class="hint">Bảng xếp hạng từ tài khoản thật trên server này, xếp theo điểm đấu và cấp.</p><div class="table-wrap"><table><thead><tr><th>Hạng</th><th>Runner</th><th>Cấp</th><th>Điểm đấu</th></tr></thead><tbody>${players.map((r,i)=>`<tr class="${r.id===online.id?'you':''}"><td>${i+1}</td><td>${esc(r.name)}</td><td>${r.level}</td><td>${r.score}</td></tr>`).join('')}</tbody></table></div>`;const runners=Array.from({length:12},(_,i)=>({name:['NULL','Mika.exe','Ghost Wire','Redline','NoSignal','Vex','Echo-7','Kha','Raven','Linh','Circuit','Kite'][i],score:300-i*24,level:30-i*2}));runners.push({name:s.name,score:Math.max(0,s.wins*25-s.losses*10),level:s.level,you:true});runners.sort((a,b)=>b.score-a.score);return `<p class="hint">Bảng xếp hạng cục bộ, các runner khác là dữ liệu mô phỏng.</p><div class="table-wrap"><table><thead><tr><th>Hạng</th><th>Runner</th><th>Cấp</th><th>Điểm đấu</th></tr></thead><tbody>${runners.map((r,i)=>`<tr class="${r.you?'you':''}"><td>${String(i+1).padStart(2,'0')}</td><td>${esc(r.name)}${r.you?' / BẠN':''}</td><td>${r.level}</td><td>${r.score}</td></tr>`).join('')}</tbody></table></div>`;}
case 'account':return profileView({s,online,world,section:profileSection,activeBadgeSlot,esc,button,auth:authView()});
case 'codex':return `<div class="hero"><div class="eyebrow">DATABASE / ${contentCount} RECORDS</div><h1>Kho dữ liệu<br><span>thành phố tro.</span></h1><p>Thế giới và nội dung riêng lấy cảm hứng từ RPG văn bản cyberpunk. Nội dung được tạo theo mẫu có phân cấp; có chế độ khách và tài khoản online.</p></div><div class="grid">${Object.entries(content).map(([k,v],i)=>card(['Khu vực','Trang bị','NPC','Địch PvE','Boss','Nhiệm vụ'][i],`<strong class="big">${v.length}</strong> hồ sơ`)).join('')}</div><article class="card"><h3>Cách chơi</h3><p>Nhận nhiệm vụ tại khu vực phù hợp → khám phá và hạ địch → nhận thưởng → mua, trang bị và di chuyển tới khu vực mới. Nghỉ tại trạm để hồi đầy HP và năng lượng. Boss gây xung điện mỗi lượt thứ ba; thuốc hồi 45 HP nhưng vẫn tiêu tốn lượt.</p><p>Chế độ khách lưu trên thiết bị; chế độ tài khoản lưu trên server. Tên runner tối đa 24 ký tự.</p><form id="name-form"><input name="runner" maxlength="24" aria-label="Tên runner" value="${esc(s.name)}"><button>Đổi tên</button></form><p>${online?'Nhân vật online được lưu trên server.':button('Bắt đầu lại','reset')}</p></article>`;
}}
