 document.querySelector('#app').innerHTML=`<aside><a class="brand" href="#" data-action="nav" data-id="hub">CYPER<span>// ZERO</span></a><div class="sub-brand">TEXT RPG · THÀNH PHỐ TRO</div><nav aria-label="Menu chức năng">${navigation({tabs,tab,admin:online?.admin,activeCount:s.active.length,label:v=>uiLabel(v,preferences.language)})}</nav><div class="aside-foot"><i></i> ${online?'SERVER SESSION':'LOCAL SESSION'}<br><small>${online?'Tiến trình lưu trên server':'Tiến trình tự lưu trên thiết bị'}</small></div></aside>${workspace?inventoryPane(inventory(true),online):''}<div style="--aura:${aura}" class="main ${showCombat?'combat-active':''} ${showLoot?'loot-active':''} ${tab==='chat'?'comms-layout':''} ${tab==='account'?'profile-layout':''} ${tab==='settings'?'settings-layout':''} ${compact?'city-layout':''} ${selectedGear?'show-detail':''} ${tab==='dungeon'&&s.dungeon?'dungeon-active':''}"><header><details class="mobile-menu"><summary aria-label="Mở menu"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg></summary><div>${navigation({tabs,tab,admin:online?.admin,activeCount:s.active.length,label:v=>uiLabel(v,preferences.language)})}</div></details><span class="header-location">${uiLabel(tabs.find(t=>t[0]===tab)[2],preferences.language).toLocaleUpperCase('vi')}</span><span class="connection-state" role="status" ${platformStatus().connected&&platformStatus().reachable?'hidden':''}>${online?'Mất kết nối · thử lại khi có mạng':'Chơi khách · ngoại tuyến'}</span><span class="wallet">${s.credits.toLocaleString('vi')} ₡ <small>${resources(s).units} U</small></span></header>${(showCombat||tab==='afk'||!workspace&&['account','chat','inventory','settings'].includes(tab)||tab==='dungeon'&&s.dungeon)?'':compactPlayer(st)}${(compact||workspace)&&tab!=='afk'?`<button class="chat-ticker" data-action="nav" data-id="chat">${ticker}</button>`:''}<main><div class="server-banner" role="status" ${!world?.management?.maintenance&&!world?.management?.announcement?'hidden':''}>${esc([world?.management?.maintenance?'SERVER ĐANG BẢO TRÌ':'',world?.management?.announcement?.text||''].filter(Boolean).join(' · '))}</div><div class="client-notice" role="status" ${clientNotice?'':'hidden'}><span>${esc(clientNotice)}</span>${button('×','client-notice-close')}</div>${tab==='hub'?introCards():''}${s.work&&tab!=='commercial'&&tab!=='afk'&&tab!=='settings'?`<div class="work-resume">${workPanel(s,button,esc)}${button('Đến khu thương mại','nav','commercial')}</div>`:''}${s.dungeon&&tab!=='dungeon'?`<div class="dungeon-resume">${button('▥ Tiếp tục dungeon · tầng '+s.dungeon.floor,'nav','dungeon')}</div>`:''}${s.pendingLoot&&!showLoot&&!s.combat?`<div class="loot-resume">${button('Chiến lợi phẩm đang chờ · Mở danh sách','loot-open')}</div>`:''}${notice?`<div class="notice" role="status">${esc(notice)}</div>`:''}${page()}</main><footer>CYPER // ZERO <span>v${appVersion} / ${online?'Online':'Khách cục bộ'} · ${contentCount} mục nội dung</span></footer></div>${workspace?communicationsPane(communications(),chatMode):''}<div class="bottom-nav" role="navigation" aria-label="Điều hướng chính">${[['hub','◫','Bản đồ'],['inventory','▣','Túi đồ'],['missions','≡','Nhiệm vụ'],['chat','▱','Trò chuyện'],['account','◎','Hồ sơ']].map(([id,icon,label])=>`<button class="${tab===id||(id==='account'&&['settings','admin'].includes(tab))||(id==='hub'&&['map','rail','station','printer','bank','exchange','shop','black','dungeon','terminal','commercial','afk','bazaar','alley','pets','tavern','coast','market','medical','cosmetics','housing','headquarters','corporation'].includes(tab))?'active':''}" data-action="nav" data-id="${id}"><span>${navIcon(id)}</span>${uiLabel(label,preferences.language)}${id==='missions'&&s.active.length||id==='chat'&&((world?.messages.at(-1)?.time||0)>lastSeenChat||(world?.guildMessages.at(-1)?.time||0)>lastSeenGuild||world?.mail.some(m=>m.recipient===online?.id&&!m.read)||s.notifications?.some(n=>!n.read))?'<i></i>':''}</button>`).join('')}</div>${modalView()}`;
 const modal=document.querySelector('.modal-overlay');if(modal)modal.querySelector('button')?.focus();
