 for(const panel of openUIPanels){const details=document.querySelector(`[data-ui-panel="${panel}"]`);if(details)details.open=true;}
 const resetDungeonScroll=showCombat&&!wasCombat||showLoot&&!wasLoot||tab==='dungeon'&&s.dungeon&&(!wasDungeon||!!s.combat!==wasDungeonCombat);
