function mobileLayout(){return matchMedia('(max-width:680px), (max-width:1000px) and (max-height:500px)').matches;}
function layoutDungeon(){
 const dock=document.querySelector('.dungeon-control-dock'),map=document.querySelector('.dungeon-grid-wrap'),navigation=document.querySelector('.dungeon-navigation');
 if(!dock||!map||!navigation)return;
 dock.classList.toggle('is-fighting',!!s.combat);
 // Keep the floating dock outside main's UI-size zoom when fixed to the viewport.
 const parent=mobileLayout()||desktopWorkspace()?document.querySelector('.dungeon-active'):navigation;
 if(dock.parentElement!==parent)parent.append(dock);
 map.style.maxWidth='';
 if((!mobileLayout()&&!desktopWorkspace())||s.combat)return;
 const grid=map.querySelector('.dungeon-grid'),box=map.getBoundingClientRect(),gridBox=grid.getBoundingClientRect(),zoom=box.width/map.offsetWidth;
 const landscape=mobileLayout()&&innerWidth>=560&&innerHeight<=500&&innerWidth>innerHeight;
 const lowerEdge=landscape?document.querySelector('.bottom-nav').getBoundingClientRect().top:dock.getBoundingClientRect().top;
 const available=lowerEdge-box.top-(box.height-gridBox.height)-26;
 map.style.maxWidth=Math.max(150,(available*s.dungeon.width/s.dungeon.height+box.width-gridBox.width)/zoom)+'px';
}
function layoutCombat(){
 const deck=document.querySelector('.combat-command-deck'),main=document.querySelector('.combat-active');
 if(!deck||!main)return;
 if(deck.parentElement!==main)main.append(deck);
 const box=main.getBoundingClientRect(),nav=document.querySelector('.bottom-nav'),navigation=nav?.getBoundingClientRect();
 const offset=navigation?.height?Math.max(0,innerHeight-navigation.top)+8:12;
 main.style.setProperty('--combat-nav-offset',offset+'px');
 deck.style.left=(Math.max(0,box.left)+14)+'px';
 deck.style.right=(Math.max(0,innerWidth-box.right)+14)+'px';
 const deckBox=deck.getBoundingClientRect();
 main.style.setProperty('--combat-deck-height',deckBox.height+'px');
 const stage=document.querySelector('.battle-stage'),landscape=matchMedia('(min-width:560px) and (max-width:1000px) and (max-height:500px) and (orientation:landscape)').matches;
 if(stage&&!landscape){const scene=stage.getBoundingClientRect(),zoom=scene.width/stage.offsetWidth,impact=document.querySelector('.battle-last-hit')?.getBoundingClientRect().height||0;stage.style.minHeight='80px';stage.style.height=Math.max(80,Math.min(430,(deckBox.top-scene.top-impact-24)/zoom))+'px';}
 const log=document.querySelector('.battle-log-entries');if(log)log.scrollTop=log.scrollHeight;
}
function sizeChat(){const screen=document.querySelector('.comms-screen.chat-mode'),nav=document.querySelector('.bottom-nav');if(!screen||!nav)return;if(mobileLayout()){screen.style.minHeight='0';screen.style.height=Math.max(180,nav.getBoundingClientRect().top-screen.getBoundingClientRect().top-8)+'px';}else{screen.style.height='';screen.style.minHeight='';}}
window.addEventListener('resize',()=>{if(desktopWorkspace()!==document.documentElement.classList.contains('desktop-workspace'))render();sizeChat();layoutDungeon();layoutCombat();layoutLoot();});

setInterval(()=>{
 if(!s.work)return;const p=workSkipPlan(s),remaining=p.remaining;
 document.querySelectorAll('[data-work-clock]').forEach(el=>el.textContent=remaining?'Còn '+duration(remaining):'Hoàn thành · có thể nhận thưởng');
 document.querySelectorAll('[data-action="work-claim"]').forEach(el=>el.disabled=busy||remaining>0);
 document.querySelectorAll('[data-work-bar]').forEach(el=>el.style.width=Math.max(0,Math.min(100,(Date.now()-s.work.startedAt)/Math.max(1,s.work.endsAt-s.work.startedAt)*100))+'%');
 document.querySelectorAll('[data-work-skip-cost]').forEach(el=>el.textContent=p.cost);
 document.querySelectorAll('[data-action="work-skip"]').forEach(el=>{el.disabled=busy||!p.can;el.dataset.cost=p.cost;el.textContent=`Dùng ${p.cost} Unit & nhận thưởng`;});
 document.querySelectorAll('[data-work-skip-note]').forEach(el=>el.textContent=remaining?(p.can?'Xác nhận bên dưới để dùng Unit.':'Không đủ Unit. Bạn có thể tiếp tục chờ miễn phí.'):'Công việc đã xong. Nhận thưởng miễn phí.');
},1000);

function introCards(){const p=settings(s);return `${!p.disableTutorial&&!s.tutorialDismissed&&s.level===1?`<details class="intro-card" data-ui-panel="welcome"><summary>Chào mừng, runner · Hướng dẫn bắt đầu</summary><p>Nhận hợp đồng trước khi khám phá. Máy in và trạm nghỉ giúp bạn chuẩn bị cho chuyến đi.</p>${button('Xem hướng dẫn','nav','codex')}${button('Đã hiểu','tutorial-dismiss')}</details>`:''}${!p.hideUpdates&&s.seenUpdateVersion!==appVersion?`<details class="intro-card" data-ui-panel="updates"><summary>CYPER // ZERO · v${appVersion} · Có gì mới?</summary><p>Chữ tiếng Việt rõ hơn với font đóng gói sẵn, cỡ chữ lớn hơn và thông tin phụ sáng hơn. Giao diện trang bị, chat và chiến đấu vẫn gọn trên điện thoại.</p>${button('Đã đọc','updates-dismiss')}${button('Cài đặt','settings-open')}</details>`:''}`;}
function modalView(){if(afkPending)return afkConfirmView({pending:afkPending,s,esc,button});if(pendingDelete)return `<div class="modal-overlay"><section role="dialog" aria-modal="true" aria-labelledby="delete-title"><h2 id="delete-title">XÓA VĨNH VIỄN TÀI KHOẢN?</h2><p>Nhân vật ${esc(pendingDelete.confirmName)}, tài sản, tin rao và thư sẽ bị xóa. Thao tác không thể khôi phục.</p><div class="actions">${button('Giữ tài khoản','delete-cancel')}${button('Xác nhận xóa vĩnh viễn','delete-confirm')}</div></section></div>`;if(victoryModal)return `<div class="modal-overlay"><section class="victory-screen" role="dialog" aria-modal="true" aria-labelledby="victory-title"><small>${victoryModal.pvp?'PVP':'PVE'} / THẮNG TRẬN</small><h2 id="victory-title">TÍN HIỆU SỐNG SÓT</h2><p>${esc(victoryModal.name)}</p><strong>+${victoryModal.xp} XP · +${victoryModal.credits} ₡</strong><p>Phần thưởng đã được cộng vào nhân vật.</p>${button('Tiếp tục','victory-close')}</section></div>`;return '';}
async function submitSettings(e){if(busy)return;if(e.target.id==='delete-form'){const f=new FormData(e.target),name=f.get('confirmName'),password=f.get('password');if(!online||name!==s.name||password.length<8||password.length>128){notice='Nhập đúng bí danh hiện tại và mật khẩu.';render();return;}pendingDelete={confirmName:name,password};render();return;}busy=true;try{const values={...settingsDraft};if(online){const result=await request('/api/action',{action:'settings',values});s=result.state;online=result.user;}else if(!settingsAction(s,{action:'settings',values}))throw new Error('Cài đặt không hợp lệ.');settingsDraft={...settings(s)};notice=settings(s).language==='en'?'Settings saved.':'Đã áp dụng và lưu cài đặt.';}catch(error){notice=error.message;}finally{busy=false;render();}}
async function confirmDeletion(){if(!online||!pendingDelete||busy)return;busy=true;try{await request('/api/account/delete',{...pendingDelete,confirm:true});pendingDelete=null;online=null;uiBoot=false;s=fresh();try{const saved=JSON.parse(localStorage.getItem('cyper-save'));if(saved?.version===1)s=saved;}catch{}settingsDraft=null;tab='account';profileSection='auth';chatDrafts={};mailDraft='';replyId=null;clientNotice='';await Promise.all([refreshWorld(),refreshPlayers()]);notice='Tài khoản online đã được xóa. Nhân vật khách trên thiết bị được giữ lại.';}catch(error){pendingDelete=null;notice=error.message;}finally{busy=false;render();}}
function notifyClient(kind,message){clientNotice=message;sounds.play(kind);if(document.hidden&&'Notification' in window&&Notification.permission==='granted')try{new Notification('CYPER // ZERO',{body:message,tag:'cyper-'+kind});}catch{}const banner=document.querySelector('.client-notice');if(banner){banner.hidden=false;banner.querySelector('span').textContent=message;}}
function watchWorld(previous,next){if(!previous||!online)return;const p=settings(s),oldIds=new Set(previous.messages.map(m=>m.id)),oldMail=new Set(previous.mail.map(m=>m.id));if(next.messages.some(m=>!oldIds.has(m.id)&&m.author!==online.id&&(m.text||'').includes('@'+s.name)))notifyClient('mention','Có tin mới nhắc đến @'+s.name);if(next.mail.some(m=>!oldMail.has(m.id)&&m.recipient===online.id))notifyClient('mail','Bạn có thư mới.');if(p.notifyGuild&&previous.corporation===next.corporation&&next.guildMessages.some(m=>!previous.guildMessages.some(old=>old.id===m.id)&&m.author!==online.id))notifyClient('notice','Kênh tập đoàn có tin mới.');if(p.notifyWorld&&next.funds.some(f=>f.active&&!previous.funds.find(old=>old.id===f.id)?.active))notifyClient('notice','Buff cộng đồng vừa được kích hoạt.');}
document.addEventListener('pointerdown',()=>{sounds.unlock();},{passive:true});document.addEventListener('keydown',()=>{sounds.unlock();});document.addEventListener('visibilitychange',()=>{if(document.hidden)sounds.pause();else sounds.resume();});window.addEventListener('pagehide',()=>sounds.dispose());

function updateConnectionUI(){
 const p=platformStatus(),badge=document.querySelector('.connection-state');
 if(badge){badge.hidden=p.connected&&p.reachable;badge.textContent=online?'Mất kết nối · thử lại khi có mạng':'Chơi khách · ngoại tuyến';}
 const panel=document.querySelector('.platform-panel');
 if(panel&&!panel.contains(document.activeElement))panel.outerHTML=platformView({online,esc,button,unsafeUpdate:busy||!!s.combat||!!s.work||!!pendingDelete||!!adminPending});
}
function handleNativeBack(){
 if(busy)return true;
 const menu=document.querySelector('.mobile-menu[open]');
 if(menu){menu.open=false;return true;}
 if(pendingDelete){pendingDelete=null;render();return true;}
 if(victoryModal){victoryModal=null;render();return true;}
 if(adminPending){adminPending=null;render();return true;}
 if(selectedGear){selectedGear=null;render();return true;}
 if(publicProfile){publicProfile=null;render();return true;}
 if(tab==='settings'){tab=settingsReturn;settingsDraft=null;render();return true;}
 if(tab==='account'&&profileSection!=='profile'){profileSection='profile';render();return true;}
 if(tab!=='hub'){tab='hub';render();scrollGameTop();return true;}
 return false;
}

async function applyAuthentication(result){
 online=result.user;s=result.state;uiBoot=false;profileSection='profile';chatDrafts={};mailDraft='';mailRecipient='';replyId=null;chatMode='global';tab='hub';
 await Promise.all([refreshPlayers(),refreshWorld()]);
}
async function connectGoogle(password){
 if(busy)return;busy=true;googleBusy=true;notice='';render();
 try{const result=await startGoogleLogin(password);if(result){await applyAuthentication(result);notice=password===undefined?'Đã đăng nhập bằng Google.':'Đã liên kết Google và giữ nhân vật hiện tại.';}}
 catch(error){notice=error.message;}
 finally{busy=false;googleBusy=false;render();}
}

function layoutLoot(){
 const screen=document.querySelector('.loot-screen'),deck=document.querySelector('.loot-command-deck'),container=document.querySelector('.main');
 if(!screen||!deck||!container)return;
 if(deck.parentElement!==container)container.append(deck);
 const rect=container.getBoundingClientRect(),nav=document.querySelector('.bottom-nav')?.getBoundingClientRect();
 const width=Math.max(200,Math.min(480,rect.width-32)),bottom=nav&&nav.right>rect.left&&nav.left<rect.right?Math.max(8,innerHeight-nav.top+8):16;
 deck.style.setProperty('--loot-left',`${rect.left+(rect.width-width)/2}px`);
 deck.style.setProperty('--loot-width',`${width}px`);deck.style.setProperty('--loot-bottom',`${bottom}px`);
 screen.style.setProperty('--loot-deck-height',`${deck.getBoundingClientRect().height}px`);
}
